XFStyleContainer::XFStyleContainer(OUString strStyleNamePrefix)
    :m_strStyleNamePrefix(std::move(strStyleNamePrefix))
{
}
#include <xfilter/xftextstyle.hxx>
#include <xfilter/xfparastyle.hxx>
